"use client";
import { useState } from "react";
import { ChevronDown, ChevronUp, Search } from "lucide-react";

const faqData = [
  {
    category: "Đặt hàng & Thanh toán",
    questions: [
      { q: "Làm thế nào để đặt hàng?", a: "Bạn chỉ cần chọn sản phẩm, thêm vào giỏ hàng, điền thông tin giao hàng và chọn phương thức thanh toán. Đơn hàng sẽ được xác nhận qua email và SMS." },
      { q: "FashionShop hỗ trợ những phương thức thanh toán nào?", a: "Chúng tôi hỗ trợ: Thanh toán khi nhận hàng (COD), Chuyển khoản ngân hàng, Thanh toán bằng thẻ Visa/Mastercard/JCB." },
      { q: "Tôi có thể hủy đơn hàng không?", a: "Bạn có thể hủy đơn hàng khi đơn hàng ở trạng thái 'Chờ xác nhận'. Sau khi đơn hàng được xử lý, vui lòng liên hệ hotline để được hỗ trợ." },
      { q: "Mã giảm giá sử dụng như thế nào?", a: "Tại trang giỏ hàng, nhập mã giảm giá vào ô 'Mã giảm giá' và nhấn 'Áp dụng'. Giảm giá sẽ được tính vào tổng đơn hàng." }
    ]
  },
  {
    category: "Vận chuyển",
    questions: [
      { q: "Thời gian giao hàng bao lâu?", a: "Giao hàng tiêu chuẩn: 3-5 ngày làm việc. Giao hàng nhanh: 1-2 ngày làm việc. Thời gian có thể thay đổi tùy theo khu vực." },
      { q: "Phí vận chuyển được tính như thế nào?", a: "Miễn phí vận chuyển cho đơn hàng trên 500.000đ. Đơn hàng dưới 500.000đ: phí giao hàng tiêu chuẩn 30.000đ, giao hàng nhanh 50.000đ." },
      { q: "Tôi có thể theo dõi đơn hàng không?", a: "Có, bạn có thể theo dõi trạng thái đơn hàng trong mục 'Tài khoản' → 'Đơn hàng của tôi'." }
    ]
  },
  {
    category: "Đổi trả & Bảo hành",
    questions: [
      { q: "Chính sách đổi trả như thế nào?", a: "FashionShop hỗ trợ đổi trả miễn phí trong 7 ngày kể từ ngày nhận hàng, với điều kiện sản phẩm chưa qua sử dụng, còn nguyên tem mác." },
      { q: "Sản phẩm bị lỗi thì xử lý thế nào?", a: "Nếu sản phẩm bị lỗi do nhà sản xuất, chúng tôi sẽ đổi mới hoàn toàn hoặc hoàn tiền 100%. Vui lòng liên hệ hotline trong 48 giờ sau khi nhận hàng." },
      { q: "Tôi muốn đổi size thì làm sao?", a: "Bạn liên hệ hotline 1900 xxxx hoặc gửi yêu cầu qua trang Liên hệ. Chúng tôi sẽ hỗ trợ đổi size miễn phí trong 7 ngày." }
    ]
  },
  {
    category: "Tài khoản",
    questions: [
      { q: "Làm thế nào để tạo tài khoản?", a: "Nhấn vào biểu tượng người dùng trên thanh menu, chọn 'Đăng ký' và điền thông tin. Bạn cũng có thể đăng ký bằng Google hoặc Facebook." },
      { q: "Tôi quên mật khẩu, phải làm sao?", a: "Nhấn 'Quên mật khẩu' tại trang đăng nhập, nhập email đã đăng ký. Chúng tôi sẽ gửi hướng dẫn khôi phục mật khẩu qua email." }
    ]
  }
];

export function FAQPage() {
  const [openItems, setOpenItems] = useState({});
  const [searchQuery, setSearchQuery] = useState("");

  const toggleItem = (catIdx, qIdx) => {
    const key = `${catIdx}-${qIdx}`;
    setOpenItems((prev) => ({ ...prev, [key]: !prev[key] }));
  };

  const filteredFAQ = searchQuery.trim()
    ? faqData.map(cat => ({
        ...cat,
        questions: cat.questions.filter(
          q => q.q.toLowerCase().includes(searchQuery.toLowerCase()) ||
               q.a.toLowerCase().includes(searchQuery.toLowerCase())
        )
      })).filter(cat => cat.questions.length > 0)
    : faqData;

  return (
    <div className="max-w-4xl mx-auto px-4 py-8">
      <div className="text-center mb-12">
        <h1 className="text-4xl font-bold mb-4">Câu Hỏi Thường Gặp</h1>
        <p className="text-gray-600 mb-8">Tìm câu trả lời nhanh cho các thắc mắc của bạn</p>
        <div className="relative max-w-md mx-auto">
          <input
            type="text"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            placeholder="Tìm kiếm câu hỏi..."
            className="w-full px-4 py-3 pl-12 border rounded-lg focus:outline-none focus:ring-2 focus:ring-orange-500"
          />
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
        </div>
      </div>

      <div className="space-y-8">
        {filteredFAQ.map((category, catIdx) => (
          <div key={catIdx}>
            <h2 className="text-xl font-bold mb-4 text-orange-500">{category.category}</h2>
            <div className="space-y-2">
              {category.questions.map((item, qIdx) => {
                const key = `${catIdx}-${qIdx}`;
                const isOpen = openItems[key];
                return (
                  <div key={qIdx} className="border rounded-lg overflow-hidden">
                    <button
                      onClick={() => toggleItem(catIdx, qIdx)}
                      className="w-full flex items-center justify-between p-4 text-left hover:bg-gray-50"
                    >
                      <span className="font-medium pr-4">{item.q}</span>
                      {isOpen ? (
                        <ChevronUp className="w-5 h-5 flex-shrink-0 text-orange-500" />
                      ) : (
                        <ChevronDown className="w-5 h-5 flex-shrink-0 text-gray-400" />
                      )}
                    </button>
                    {isOpen && (
                      <div className="p-4 pt-0 text-gray-600 border-t bg-gray-50">
                        {item.a}
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
